import React from 'react';

const TableViewComponent = ({ results }) => {
  if (!results || !results.length) {
    return <div>No results found.</div>;
  }

  return (
    <table className="results-table table-auto w-full border-collapse border border-gray-300">
      <thead>
        <tr className="bg-gray-100 dark:bg-gray-700">
          <th className="border p-2 text-left">Title</th>
          <th className="border p-2 text-left">Categories</th>
          <th className="border p-2 text-left">Year</th>
        </tr>
      </thead>
      <tbody>
        {results.map((result, index) => (
          <tr key={index} className="border-t hover:bg-gray-50 dark:hover:bg-gray-800">
            <td className="border p-2">
              <a
                href={result.full_title}
                className="text-blue-600 hover:underline dark:text-blue-300"
              >
                {result.title}
              </a>
            </td>
            <td className="border p-2">
              <span
                className="flex flex-wrap items-center gap-1"
                data-toggle="tooltip"
                data-placement="bottom"
                title="Categories"
              >
                <i className="fal fa-tags mr-1 text-gray-500 dark:text-gray-300"></i>
                {result.category && result.category.length > 0 ? (
                  result.category.map((cat, idx) => (
                    <a
                      key={idx}
                      href={`/${cat.link}`}
                      title={`Category: ${cat.name}`}
                      className="subject-links text-blue-500 hover:underline dark:text-blue-300 text-sm mr-2"
                    >
                      {cat.name}
                    </a>
                  ))
                ) : (
                  <span className="text-gray-500">—</span>
                )}
              </span>
            </td>
            <td className="border p-2">
              {result.year || <span className="text-gray-500">—</span>}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default TableViewComponent;
